"""The per-utterance transcription recorder and its factories."""

from __future__ import annotations

from contextvars import ContextVar
from typing import TYPE_CHECKING, Optional

from opentelemetry import trace
from opentelemetry.trace import Span

from rasa.tracing.voice.metrics import (
    VoiceComponent,
    VoiceOperation,
    record_operation_failure_metric,
)
from rasa.tracing.voice.recorders.asr.span_attributes import engine_attributes
from rasa.tracing.voice.shared import semconv
from rasa.tracing.voice.spans import (
    content_capture_enabled,
    set_span_error,
    start_voice_span,
    voice_observability_enabled,
)

if TYPE_CHECKING:
    from rasa.core.channels.voice_stream.asr.asr_engine import ASREngine
    from rasa.core.channels.voice_stream.asr.asr_event import ASREvent


class TranscribeAudioRecorder:
    """Record tracing and failure metrics for one user utterance.

    In metrics-only mode, the recorder skips span updates but still emits
    failure metrics. A detached recorder emits neither signal.

    Args:
        span: Span for this utterance. It is non-recording in metrics-only mode.
        asr_provider_name: Provider name returned by ``ASREngine.name()``.
            Added to failure metrics as the ``provider`` attribute.
    """

    # Sample interim events to stay below OpenTelemetry's default limit of
    # 128 events per span; retain the full number in an attribute.
    PARTIAL_EVENT_SAMPLE_RATE = 10

    def __init__(self, span: Span, *, asr_provider_name: Optional[str] = None) -> None:
        # Identity and signal state.
        self.span = span
        self._asr_provider_name = asr_provider_name
        self._emit_metrics = True
        # Transcript state and duplicate-failure guard.
        self._failed = False
        self._partial_count = 0

    @classmethod
    def detached(cls) -> "TranscribeAudioRecorder":
        """Return a recorder that emits neither spans nor metrics."""
        recorder = cls(trace.INVALID_SPAN)
        recorder._emit_metrics = False
        return recorder

    def record_partial(self) -> None:
        """Record an interim transcript without its text."""
        self._partial_count += 1
        is_sampled = (self._partial_count - 1) % self.PARTIAL_EVENT_SAMPLE_RATE == 0
        if is_sampled and self.span.is_recording():
            self.span.add_event(semconv.EVENT_PARTIAL_TRANSCRIPT)

    def record_final(self, text: str) -> "TranscribeAudioRecorder":
        """Record the final transcript.

        The span includes the text only when content capture is enabled.
        """
        if self.span.is_recording():
            self.span.add_event(semconv.EVENT_FINAL_TRANSCRIPT)
            if content_capture_enabled():
                self.span.set_attribute(semconv.VOICE_TRANSCRIPT_FINAL, text)
        return self

    def record_error(self, error: BaseException) -> "TranscribeAudioRecorder":
        """Record an ASR failure and mark the span as failed.

        Only the first error increments the failure counter.
        """
        if self._emit_metrics and not self._failed:
            record_operation_failure_metric(
                component=VoiceComponent.ASR,
                operation=VoiceOperation.TRANSCRIBE,
                error=error,
                provider=self._asr_provider_name,
            )
        self._failed = True
        if self.span.is_recording():
            self.span.add_event(semconv.EVENT_ASR_ERROR)
            set_span_error(self.span, error)
        return self

    def end(self) -> None:
        """End the span and clear the current recorder."""
        if self.span.is_recording():
            self.span.set_attribute(
                semconv.PARTIAL_TRANSCRIPT_COUNT, self._partial_count
            )
        # Always clear the recorder so the next utterance gets a fresh one.
        self.span.end()
        _current_transcription_recorder.set(None)


_current_transcription_recorder: ContextVar[Optional[TranscribeAudioRecorder]] = (
    ContextVar("rasa_voice_transcription", default=None)
)


def get_or_create_transcribe_audio_recorder(
    engine: "ASREngine",
) -> TranscribeAudioRecorder:
    """Return the open utterance's recorder or create one for a new utterance.

    Reuses the active recorder for later events from the same utterance.
    In metrics-only mode, the recorder uses a non-recording span. When voice
    observability is disabled, this returns an unbound detached recorder.
    """
    if not voice_observability_enabled():
        return TranscribeAudioRecorder.detached()

    transcription_recorder = _current_transcription_recorder.get()
    if transcription_recorder is not None:
        return transcription_recorder
    span = start_voice_span(
        semconv.SPAN_NAME_TRANSCRIBE_AUDIO, attributes=engine_attributes(engine)
    )
    transcription_recorder = TranscribeAudioRecorder(
        span, asr_provider_name=engine.name()
    )
    _current_transcription_recorder.set(transcription_recorder)
    return transcription_recorder


def get_current_transcribe_audio_recorder() -> TranscribeAudioRecorder:
    """Return the open utterance's recorder.

    Between utterances (and when tracing is disabled) returns a detached
    no-op recorder, so callers can record unconditionally.
    """
    transcription_recorder = _current_transcription_recorder.get()
    if transcription_recorder is not None:
        return transcription_recorder
    return TranscribeAudioRecorder.detached()


def trace_asr_event(asr_event: "ASREvent", engine: "ASREngine") -> None:
    """Update the current transcription recorder from an ASR event.

    The first interim opens the recorder and a final transcript closes it.
    A final without an interim still gets a recorder. Empty finals and
    unrelated ASR events are ignored when no utterance is active.
    """
    if not voice_observability_enabled():
        return

    from rasa.core.channels.voice_stream.asr.asr_event import (
        NewTranscript,
        UserIsSpeaking,
    )

    if isinstance(asr_event, UserIsSpeaking):
        get_or_create_transcribe_audio_recorder(engine).record_partial()
    elif isinstance(asr_event, NewTranscript):
        if _current_transcription_recorder.get() is None and not asr_event.text:
            return
        get_or_create_transcribe_audio_recorder(engine).record_final(
            asr_event.text
        ).end()
